const procedures={
'ORG-001':{purpose:'Mỗi nhiệm vụ có người phụ trách, người kiểm tra và người thay thế.',frequency:'Đầu ca; khi thay đổi nhân sự hoặc cơ cấu.',input:'Danh sách nhân sự, kỹ năng được chứng nhận và nhu cầu vị trí.',tools:'Sơ đồ tổ chức; lịch ca; bảng phân công; ma trận quyền.',steps:['Chủ quán chỉ định quản lý và người thay thế.','Quản lý xác định các vị trí phải được phủ trong từng ca.','Đối chiếu skill matrix trước khi phân công.','Ghi người phụ trách, người kiểm tra và người thay trên bảng đầu ca.','Thông báo quyền xử lý tiền, món không đạt và sự cố.','Khi đổi vị trí, cập nhật bảng và bàn giao công việc.','Cuối ca, kiểm hồ sơ trọng yếu đã có người xác nhận.'],pass:'Mọi vị trí có người đủ kỹ năng; nhân viên biết báo ai.',fail:'Giao vị trí chưa được đào tạo; không có người quyết định khi quản lý vắng.',critical:'Mọi nhân viên được dừng thao tác có nguy cơ mất an toàn và báo quản lý.',fix:'Chỉ định lại owner; kiểm công việc bị bỏ sót; cập nhật bàn giao.',checks:['Có quản lý ca','Có người thay thế','Đủ vị trí trọng yếu','Đã kiểm kỹ năng','Đã công bố quyền xử lý','Đã xác nhận bàn giao']},
'HR-001':{purpose:'Tuyển đúng yêu cầu; không giao việc độc lập khi chưa đủ kỹ năng.',frequency:'Mỗi đợt tuyển; mỗi nhân viên mới hoặc chuyển vị trí.',input:'Nhu cầu tuyển được duyệt; JD; người hướng dẫn được chỉ định.',tools:'JD; phiếu phỏng vấn; checklist đào tạo; skill matrix.',steps:['Duyệt nhu cầu, vị trí và điều kiện tuyển trước khi đăng tuyển.','Sàng lọc, phỏng vấn và kiểm tra thực hành có hướng dẫn.','Ghi kết quả và thống nhất điều kiện nhận việc theo chính sách đã duyệt.','Ngày đầu: giới thiệu quản lý, đồng nghiệp và đường báo cáo.','Dẫn đi từng khu: sống, chín, kho, rửa tay, rác, toilet và lối thoát.','Cấp đồng phục và quyền truy cập đúng phạm vi.','Làm mẫu rửa tay và chuyển thao tác; yêu cầu nhân viên thực hành lại.','Giao công việc có giám sát; ghi việc chưa được phép làm.','Đánh giá theo bằng chứng; ghi quyền làm độc lập; cập nhật skill matrix.'],pass:'Hoàn tất nội dung bắt buộc; đạt thực hành; có xác nhận quyền làm độc lập.',fail:'Ký đào tạo nhưng chưa thực hành; cấp quyền POS quá mức.',critical:'Đã được hướng dẫn không đồng nghĩa đã được chứng nhận.',fix:'Giữ mức có giám sát; đào tạo phần thiếu; đánh giá lại.',checks:['Có JD','Có người hướng dẫn','Đã giới thiệu an toàn','Đã thực hành','Đã đánh giá','Đã ghi quyền làm việc','Đã lưu hồ sơ']},
'HR-002':{purpose:'Kiểm soát vệ sinh cá nhân và cách làm việc với khách.',frequency:'Đầu ca; khi chuyển thao tác; khi phát hiện sai lệch.',input:'Nhân viên đã nhận nội quy và được hướng dẫn.',tools:'Đồng phục; bảo hộ tóc; nơi cất đồ; điểm rửa tay.',steps:['Mặc đồng phục sạch; thay khi bẩn; không dùng tạp dề lau tay.','Buộc/gói tóc gọn; dùng bảo hộ tóc khi xử lý thực phẩm.','Giữ móng ngắn, sạch; không dùng móng giả/sơn móng khi xử lý thực phẩm.','Tháo trang sức có thể rơi/chạm thực phẩm; dùng giày kín phù hợp nền bếp.','Cất điện thoại; rửa tay sau khi chạm điện thoại hoặc tiền trước khi xử lý thực phẩm.','Báo quản lý nếu có nôn, tiêu chảy hoặc dấu hiệu ảnh hưởng an toàn thực phẩm.','Rửa tay trước ca, sau thực phẩm sống, toilet, rác và trước thực phẩm chín.','Găng tay không thay cho rửa tay; thay khi đổi thao tác hoặc bẩn/hỏng.','Nói rõ, vừa đủ nghe; không tranh luận trước khách. Chào: “Em chào anh/chị, mình đi mấy người ạ?”'],pass:'Đạt các mục áp dụng và sửa lỗi trước khi tiếp tục.',fail:'Đồng phục bẩn; chạm tiền rồi chia rau; không báo triệu chứng.',critical:'Người có triệu chứng nghi ảnh hưởng an toàn không tự quyết tiếp tục xử lý thực phẩm.',fix:'Dừng việc bị ảnh hưởng; sửa tác phong/rửa tay; kiểm thực phẩm đã chạm; quản lý quyết định chuyển việc.',checks:['Đồng phục','Tóc','Tay / móng','Trang sức','Giày','Sức khỏe đã báo','Rửa tay','Mục không đạt đã xử lý']},
'HR-003':{purpose:'Đủ người, đủ kỹ năng và có bàn giao khi đổi ca.',frequency:'Theo kỳ lịch [ĐIỀN THỰC TẾ]; mỗi ca; khi phát sinh.',input:'Giờ mở cửa; nhu cầu bán; nhân sự và kỹ năng đã chứng nhận.',tools:'Lịch ca; chấm công; skill matrix; handover form.',steps:['Tổng hợp giờ bán và khối lượng prep dự kiến.','Xác định vị trí tối thiểu cho từng khung giờ [ĐIỀN THỰC TẾ].','Kiểm tra kỹ năng trước khi xếp vị trí.','Lập lịch, người dự phòng và giới hạn quyền.','Nhân viên xác nhận lịch qua kênh [ĐIỀN THỰC TẾ].','Chấm công đúng thực tế; sửa công phải có lý do và xác nhận.','Đổi ca chỉ có hiệu lực sau quản lý duyệt và người thay đủ kỹ năng.','Đi trễ/nghỉ đột xuất: báo quản lý; bố trí dự phòng hoặc giảm phạm vi phục vụ.','Bàn giao tồn, công việc và vấn đề chưa xử lý cho người nhận ca.'],pass:'Lịch được xác nhận; đủ vai trò trọng yếu; công đúng và có bàn giao.',fail:'Tự đổi ca; chấm hộ; người thay thiếu kỹ năng.',critical:'Số người đủ chưa đồng nghĩa đủ kỹ năng.',fix:'Điều chỉnh lịch; chuyển việc có giám sát; giảm món/khu phục vụ nếu chưa đủ người.',checks:['Lịch được duyệt','Nhân viên đã xác nhận','Đủ kỹ năng','Có dự phòng','Chấm công khớp thực tế','Đổi ca được duyệt','Bàn giao hoàn tất']},
'HR-004':{purpose:'Đánh giá bằng dữ liệu và xác định nội dung cần đào tạo.',frequency:'Theo kỳ [ĐIỀN THỰC TẾ]; xử lý lỗi an toàn ngay.',input:'Dữ liệu có thời gian, người ghi và mẫu số rõ.',tools:'POS; QC; waste log; audit; chấm công; skill matrix.',steps:['Kiểm tính đầy đủ của dữ liệu và mẫu số.','Tách lỗi cá nhân khỏi lỗi hệ thống hoặc đầu vào.','Tính KPI cùng định nghĩa giữa các chi nhánh.','Trao đổi bằng tình huống và hồ sơ cụ thể.','Ghi hành động đào tạo, sửa quy trình, thiết bị hoặc bố trí.','Chỉ định người theo dõi và thời điểm kiểm lại.','Xử lý riêng lỗi an toàn trọng yếu; không lấy doanh số bù.'],pass:'Tính được từ hồ sơ; có giải thích và kế hoạch cải thiện.',fail:'Chấm theo cảm giác; đổi mẫu số; ép tốc độ bỏ QC.',critical:'Không khuyến khích giấu waste, complaint hoặc sự cố.',fix:'Dữ liệu thiếu: ghi chưa đủ dữ liệu; bổ sung thu thập; không ước đoán điểm.',checks:['Dữ liệu kiểm được','Mẫu số đúng','Nguyên nhân xác minh','Nhân viên phản hồi','Có hành động / owner','Có ngày kiểm lại']},
'HR-005':{purpose:'Chỉ giao việc độc lập khi nhân viên chứng minh được kỹ năng.',frequency:'Nhân viên mới; chuyển vị trí; đổi SOP/recipe; đào tạo lại.',input:'Đúng phiên bản tài liệu; người hướng dẫn đủ năng lực.',tools:'SOP; recipe; thiết bị thật; checklist và bài đánh giá.',steps:['Giải thích mục tiêu và tiêu chuẩn đạt.','Người hướng dẫn làm mẫu thao tác.','Nhân viên nói lại các điểm kiểm soát.','Thực hành có giám sát.','Đánh giá thành phẩm, trình tự, vệ sinh và ghi nhận.','Chưa đạt: sửa lỗi và thực hành lại.','Đạt: ghi bằng chứng, cấp quyền theo kỹ năng, cập nhật skill matrix.'],pass:'Đủ bằng chứng theo tiêu chí được duyệt; không còn lỗi trọng yếu.',fail:'Chỉ trả lời lý thuyết; chưa thực hành; ký thay bằng chứng.',critical:'Chứng nhận theo kỹ năng cụ thể. Lỗi gây nguy cơ an toàn phải dừng bài và kiểm sản phẩm.',fix:'Đào tạo phần chưa đạt; đánh giá lại trước khi cấp quyền.',checks:['Đúng phiên bản','Đã làm mẫu','Đã thực hành','Kiểm tình huống không đạt','Kết luận từng kỹ năng','Có phạm vi quyền','Cập nhật skill matrix']},
'DOC-001':{purpose:'Mọi chi nhánh sử dụng đúng bản được duyệt.',frequency:'Khi tạo mới, sửa, ban hành hoặc thu hồi tài liệu.',input:'Nội dung có mã, owner và lý do tạo/sửa.',tools:'Master list; thư mục dùng chung; bản in kiểm soát.',steps:['Ghi mã tài liệu, nội dung sửa và lý do.','Owner kiểm tác động đến món, an toàn, cost và đào tạo.','Thử tại chi nhánh chỉ định; ghi kết quả.','Người có thẩm quyền phê duyệt.','Cập nhật version, ngày hiệu lực và revision history.','Phát hành bản mới; thu hồi bản in cũ.','Đào tạo thay đổi và ký xác nhận.','Kiểm ca đầu áp dụng.'],pass:'Phiên bản tại vị trí làm việc trùng master list; người dùng đã được đào tạo.',fail:'Recipe viết tay chưa duyệt; các chi nhánh dùng portion khác nhau.',critical:'Không đổi recipe, shelf life hoặc giới hạn an toàn bằng lời nói.',fix:'Thu hồi bản cũ; cấp bản đúng; xác minh mẻ/món ảnh hưởng; ghi khắc phục.',checks:['Có người duyệt','Có ngày hiệu lực','Master list cập nhật','Bản cũ thu hồi','Đã đào tạo','Ca đầu đã kiểm']}};
const sops=seeds.map((s,i)=>({id:s[0],code:'SOP-'+s[0],title:s[1],module:s[2],owner:s[3],group:i<30?i+1:'Bổ sung',ready:!!procedures[s[0]]}));
const checklistItems=['Nội quy và đường báo cáo','Đồng phục và tác phong','Rửa tay và chuyển thao tác','Tách thực phẩm sống / chín','Nhãn và FEFO','Menu và thành phần','Dị ứng và báo quản lý','Cân portion','Recipe theo vị trí','Nhận / xác nhận order','POS và thanh toán','Vệ sinh và hóa chất','Báo sự cố','Mở / đóng ca và bàn giao'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Không lưu được trên trình duyệt. Hãy xuất bản sao dữ liệu.');return false}}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',3500)}
function pageTitle(k,title,desc,action=''){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function moduleCard(i){return `<a class="module-card" href="#module/${i}"><div class="module-top"><span class="module-num">MODULE ${String(i).padStart(2,'0')}</span><span class="tag ${i<2?'green':'gray'}">${i<2?'Có bản dự thảo':'Chưa soạn'}</span></div><h3>${moduleVi[i]}</h3><p>${modules[i]}</p><div class="bottom"><span>${sops.filter(s=>s.module===i).length} quy trình trong danh mục</span><span>→</span></div></a>`}
function home(){return pageTitle('SỔ TAY VẬN HÀNH','Vận hành có chuẩn. Phát triển có nền.','Một nơi để tra cứu quy trình, đào tạo và kiểm tra từng ca.',`<a class="btn primary" href="#library">Tra cứu SOP ↗</a>`)+`<section class="hero"><div><div class="eyebrow">TIỆM BÚN CÁ NGỪ KHO CAY · TUY HOÀ</div><h2>Giữ đúng vị món.<br>Giữ trọn trải nghiệm.</h2><p>Hệ thống SOP dành cho đội ngũ của tiệm — từ nhân viên mới đến quản lý chi nhánh.</p><a class="btn" href="#module/0">Khám phá hệ thống <span>→</span></a></div><div class="hero-art" aria-hidden="true"><div class="bowl"></div></div></section><div class="metrics"><div class="metric"><small>QUY TRÌNH CỐT LÕI</small><strong>30</strong><span>Trong SOP Master Index</span></div><div class="metric"><small>MODULE HỆ THỐNG</small><strong>14</strong><span>Từ Module 00 đến 13</span></div><div class="metric"><small>MODULE ĐÃ CÓ DỰ THẢO</small><strong>02</strong><span>Master Index · Organization & HR</span></div><div class="metric"><small>QUY TRÌNH ĐÃ BAN HÀNH</small><strong>00</strong><span>Cần chủ quán phê duyệt</span></div></div><div class="columns"><section><div class="section-head"><h2>Thư viện vận hành</h2><a href="#library">Xem tất cả →</a></div><div class="search"><input id="home-search" aria-label="Tìm kiếm quy trình" placeholder="Tìm quy trình, mã SOP hoặc nội dung…"></div><div class="module-grid">${[0,1,2,3].map(moduleCard).join('')}</div></section><section><div class="panel"><div class="section-head"><h2>Bắt đầu nhanh</h2><span class="tag gray">Hằng ngày</span></div><a class="quick" href="#checklists"><span class="quick-icon">✓</span><div><strong>Checklist đào tạo</strong><small>Hướng dẫn · thực hành · xác nhận</small></div><b>→</b></a><a class="quick" href="#training"><span class="quick-icon">↗</span><div><strong>Lộ trình nhân viên mới</strong><small>Roadmap & ma trận kỹ năng</small></div><b>→</b></a><a class="quick" href="#documents"><span class="quick-icon">▤</span><div><strong>Kiểm soát tài liệu</strong><small>Phiên bản & dữ liệu cần bổ sung</small></div><b>→</b></a></div><div class="note"><h3>Hoàn thiện trước khi ban hành</h3><p>Công thức, định lượng, lịch ca và quyền hạn chưa được cung cấp sẽ giữ nguyên ô cần điền.</p><a class="btn" href="#documents">Xem thông tin cần bổ sung →</a></div></section></div>`}
function sopRows(list){return list.length?list.map(s=>`<tr><td><a href="#sop/${s.id}">${s.code}</a></td><td><a href="#sop/${s.id}">${s.title}</a></td><td>${String(s.module).padStart(2,'0')}</td><td>${s.owner}</td><td><span class="tag ${s.ready?'green':'gray'}">${s.ready?'Dự thảo D0.1':'Chưa soạn'}</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Không có quy trình phù hợp.</td></tr>'}
function sopTable(list){return `<div class="table-wrap"><table><thead><tr><th>Mã tài liệu</th><th>Quy trình</th><th>Module</th><th>Phụ trách</th><th>Trạng thái</th></tr></thead><tbody id="sop-rows">${sopRows(list)}</tbody></table></div>`}
function library(){return pageTitle('THƯ VIỆN','Quy trình vận hành','30 nhóm SOP cốt lõi và 3 quy trình bổ sung. Chỉ các bản đã soạn có nội dung chi tiết.')+`<div class="toolbar"><input id="search" aria-label="Tìm SOP" placeholder="Tìm theo tên, mã SOP, người phụ trách…"><select id="filter" aria-label="Lọc module"><option value="all">Tất cả module</option>${modules.map((m,i)=>`<option value="${i}">${String(i).padStart(2,'0')} · ${moduleVi[i]}</option>`).join('')}</select></div><section class="panel">${sopTable(sops)}</section>`}
function modulePage(i){if(!modules[i])return '<div class="empty">Không tìm thấy module.</div>';return pageTitle(`MODULE ${String(i).padStart(2,'0')}`,moduleVi[i],modules[i])+ (i===0?`<div class="panel"><h2>Kiến trúc hệ thống</h2><p>Manual → SOP → Hướng dẫn thao tác / Recipe / Tiêu chuẩn → Form & Checklist → QC / Audit → Khắc phục.</p><div class="meta"><div><span>Mã bộ tài liệu</span>MAN-OPS-001</div><div><span>Phiên bản</span>D0.1 · Chưa hiệu lực</div><div><span>Owner</span>Chủ quán</div><div><span>Người phê duyệt</span>[CHỦ QUÁN XÁC NHẬN]</div></div><h3>Nguyên tắc nhân rộng</h3><p>Chuẩn dùng chung: recipe, portion, nguyên liệu, nhãn, food safety, pass món, quyền điều chỉnh bill và báo cáo. Phụ lục riêng: layout, thiết bị, nhân sự, lịch ca và đầu mối từng chi nhánh.</p><h3>Điều kiện ban hành</h3><p>Điền dữ liệu → thử tại quán → sửa sai lệch → phê duyệt → đào tạo → kiểm ca đầu. Bản dự thảo không tự động trở thành tiêu chuẩn chính thức.</p></div>`:i===1?`<div class="panel"><h2>Mô hình tổ chức đề xuất</h2><p>Chủ quán → Quản lý cửa hàng → Bếp chính / Phụ bếp / Phục vụ / Thu ngân / Kho / Vệ sinh.</p><div class="callout">Các ô là vai trò, không mặc định mỗi ô cần một người riêng. Kiêm nhiệm phải bảo đảm phân tách thao tác và kiểm tra độc lập.</div><a class="btn" href="#training">Lộ trình & ma trận kỹ năng →</a></div>`:`<div class="note"><h3>Module này chưa được soạn</h3><p>Hiện chỉ có danh mục tài liệu theo yêu cầu. Nội dung sẽ được hoàn thiện theo thứ tự module; chưa dùng để hướng dẫn thao tác thực tế.</p></div>`)+`<div class="panel"><h2 style="margin-bottom:18px">${i===0?'Master Index · toàn bộ hệ thống':'Quy trình trong module'}</h2>${sopTable(i===0?sops:sops.filter(s=>s.module===i))}</div>`}
function detail(id){const s=sops.find(s=>s.id===id);if(!s)return '<div class="empty">Không tìm thấy SOP. <a href="#library">Về thư viện</a></div>';const d=procedures[id];if(!d)return pageTitle(s.code,s.title,'Danh mục dự kiến · Module '+String(s.module).padStart(2,'0'))+`<div class="note"><h3>Chưa có bản SOP chi tiết</h3><p>Người phụ trách dự kiến: ${s.owner}. Chưa có bước thao tác, thông số và tiêu chuẩn được duyệt.</p><a class="btn" href="#module/${s.module}">Về module →</a></div>`;let notes=read('notes-'+id,'');return pageTitle(s.code,s.title,'Bản dự thảo D0.1 · Chưa có ngày hiệu lực',`<button class="btn" onclick="window.print()">In SOP ↗</button>`)+`<div class="detail-grid"><section class="panel"><div class="meta"><div><span>Thực hiện / owner</span>${s.owner}</div><div><span>Kiểm tra</span>${id==='ORG-001'||id==='DOC-001'?'Chủ quán / người ủy quyền':'Quản lý / người được chỉ định'}</div><div><span>Phạm vi</span>Nhân sự và tài liệu liên quan tại các chi nhánh</div><div><span>Tần suất</span>${d.frequency}</div></div><h3>Mục đích</h3><p>${d.purpose}</p><h3>Chuẩn bị & đầu vào</h3><p>${d.input}</p><p><b>Dụng cụ:</b> ${d.tools}</p><p><b>Nguyên vật liệu:</b> không áp dụng cho quản trị; thực hành theo SOP/recipe được duyệt.</p><p><b>Thời gian:</b> hoàn tất trước khi giao việc độc lập / áp dụng thay đổi; chi tiết [ĐIỀN THỰC TẾ].</p><p><b>Nhiệt độ / định lượng:</b> không áp dụng cho quy trình quản trị; khi thực hành dùng SOP tương ứng.</p><h3 style="margin-top:25px">Trình tự thực hiện</h3><ol class="steps">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="callout"><b>Điểm kiểm soát quan trọng</b><br>${d.critical}</div><h3>Tiêu chuẩn đạt</h3><p>${d.pass}</p><h3>Không đạt / lỗi thường gặp</h3><p>${d.fail}</p><h3>Xử lý sai lệch</h3><p>${d.fix} Báo quản lý; vấn đề vượt quyền báo chủ quán.</p><h3>Ghi nhận</h3><p>Ghi người thực hiện, ngày giờ, kết quả, sai lệch, hành động và người kiểm tra. Lưu tại [ĐIỀN THỰC TẾ].</p><h3>Checklist cuối quy trình</h3><ul class="bullets">${d.checks.map(x=>`<li>☐ ${x}</li>`).join('')}</ul><p>Người thực hiện: __________ Người kiểm tra: __________ Ngày: __________</p></section><section class="detail-aside"><div class="panel"><h3>Trong tài liệu này</h3><p>Mục đích & chuẩn bị</p><p>Trình tự thực hiện</p><p>Tiêu chuẩn & xử lý</p><p>Checklist cuối</p><a class="btn" href="#module/${s.module}">← Về module</a></div><div class="note"><h3>Cần xác nhận</h3><p>Người thực hiện, quyền hạn, thời gian và nơi lưu hồ sơ phải được chủ quán duyệt.</p></div><div class="panel" style="margin-top:20px"><h3>Ghi chú của bạn</h3><textarea id="sop-note" class="edit" style="min-height:120px" aria-label="Ghi chú SOP">${esc(notes)}</textarea><button class="btn" id="save-note" style="margin-top:10px">Lưu ghi chú</button><p style="font-size:10px">Chỉ lưu trên trình duyệt; không sửa bản SOP gốc.</p></div></section></div>`}
function checklists(){let records=read('trainingRecords',[]);return pageTitle('CHECKLIST BOOK','Theo dõi đào tạo','CHK-HR-001 · Phiếu cho một nhân viên. Lưu riêng từng phiếu trên trình duyệt.')+`<section class="panel"><div class="form-grid"><label>Nhân viên<input id="employee" placeholder="Nhập họ tên"></label><label>Chi nhánh<input id="branch" placeholder="[ĐIỀN THỰC TẾ]"></label><label>Ngày<input id="record-date" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}"></label></div><div class="check-summary"><span id="check-count">0 / 14 nội dung đã đạt</span><span class="tag gray">Chưa phải chứng nhận kỹ năng</span></div><div class="progress"><div id="check-progress" style="width:0"></div></div>${checklistItems.map((x,i)=>`<div class="check-row"><label><input type="checkbox" data-check="${i}">${x}</label><select data-status="${i}" aria-label="Mức đào tạo ${x}"><option>Chưa hướng dẫn</option><option>Đã hướng dẫn</option><option>Đã thực hành</option><option>Đạt</option><option>Không áp dụng</option></select><textarea data-note="${i}" placeholder="Người xác nhận, ngày, bằng chứng hoặc lý do không áp dụng…" aria-label="Ghi nhận ${x}" rows="1"></textarea></div>`).join('')}<div class="form-grid" style="margin-top:22px"><label>Người hướng dẫn<input id="trainer" placeholder="Nhập họ tên"></label><label>Quản lý kiểm tra<input id="reviewer" placeholder="Nhập họ tên"></label><label>Vị trí<input id="position" placeholder="Bếp / Phục vụ / Thu ngân…"></label></div><div class="toolbar no-print"><button class="btn primary" id="save-record">Lưu phiếu</button><button class="btn" onclick="window.print()">In A4</button><button class="btn" id="export-records">Xuất dữ liệu JSON</button></div><p>Lưu phiếu không đồng nghĩa được chứng nhận. Quản lý cần xác minh thực hành và phạm vi quyền.</p></section><section class="panel no-print"><h2>Phiếu đã lưu</h2>${records.length?`<div class="table-wrap"><table><thead><tr><th>Nhân viên</th><th>Chi nhánh</th><th>Ngày</th><th>Nội dung đạt</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.employee)}</td><td>${esc(r.branch)}</td><td>${esc(r.date)}</td><td>${r.items.filter(i=>i.status==='Đạt').length} / 14</td><td><button class="btn load-record" data-id="${esc(r.id)}">Mở phiếu</button></td></tr>`).join('')}</tbody></table></div>`:'<p>Chưa có phiếu được lưu. Điền thông tin và nhấn “Lưu phiếu”.</p>'}</section>`}
function training(){return pageTitle('HR & TRAINING','Lộ trình & kỹ năng','Roadmap minh họa — cần chủ quán xác nhận; số ngày không tự động chứng minh năng lực.')+`<section class="panel"><h2>Lộ trình nhân viên mới</h2><table><thead><tr><th>Ngày</th><th>Nội dung</th><th>Thực hành</th></tr></thead><tbody>${[['01','Nội quy · văn hóa · vệ sinh · ATTP','Rửa tay, phân dụng cụ, báo nguyên liệu nghi ngờ'],['02','Menu · nguyên liệu · dị ứng · portion','Đọc card, cân phần, xác định thành phần chưa rõ'],['03','Thực hành theo vị trí','Prep / nấu hoặc order / POS có giám sát'],['04','Service & phối hợp ca','Mức cay, món hết, đổi món và bàn giao'],['05','Kiểm tra kiến thức & thực hành','Tình huống bình thường và không đạt']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="callout">Beginner: làm có giám sát · Trained: đã học và thực hành · Certified: đã đạt đánh giá và được cấp quyền cụ thể.</div><a class="btn primary" href="#checklists">Mở checklist đào tạo →</a></section><section class="panel"><div class="section-head"><h2>Ma trận kỹ năng</h2><button class="btn" id="add-staff">+ Thêm nhân viên</button></div><p>Ma trận tự ghi nhận; mức Certified cần liên kết hồ sơ thực hành được duyệt.</p><div class="table-wrap" id="skill-table"></div><button class="btn primary" id="save-skills" style="margin-top:15px">Lưu ma trận</button></section>`}
const missing=['Tên thương hiệu, mã và địa chỉ chi nhánh','Người phê duyệt SOP, recipe và biểu mẫu','Danh sách sáu món chính thức và recipe gốc','Ngày chạy thử, ban hành và mở chi nhánh 2','Danh sách nhân viên, vị trí và số người theo ca','Giờ mở cửa, prep, đóng cửa và khung giờ đông','Người quản lý và người thay ở từng chi nhánh','Hạn mức mua hàng, giảm giá, hủy bill và hoàn tiền','Đồng phục, giày, nơi cất đồ và nội quy hiện có','Chấm công và kênh báo nghỉ / đổi ca','JD, chế độ và chính sách nhân sự','Người hướng dẫn bếp, phục vụ và POS','Dữ liệu sai order, complaint, waste và tiền lệch','Tiêu chí thực hành và người chứng nhận','Nơi lưu hồ sơ và quyền truy cập'];
function documents(){return pageTitle('DOCUMENT CONTROL','Tài liệu & dữ liệu cần bổ sung','MAN-OPS-001 · D0.1 · Bản dự thảo chưa hiệu lực.',`<button class="btn" onclick="window.print()">In danh mục</button>`)+`<div class="panel"><h2>Quy ước thông tin</h2><div class="callout">[ĐIỀN THỰC TẾ] · [CHỦ QUÁN XÁC NHẬN] · [MINH HỌA – CẦN CHỦ QUÁN XÁC NHẬN] · [RECIPE CỦA QUÁN – ĐIỀN TẠI ĐÂY]</div><p>Không chuyển dữ liệu minh họa thành tiêu chuẩn chính thức khi chưa đo lường, thử nghiệm và phê duyệt.</p><a class="btn" href="#sop/DOC-001">Quy trình kiểm soát tài liệu →</a></div><div class="panel"><h2>Thông tin cần chủ quán bổ sung</h2>${missing.map((x,i)=>`<details><summary>${String(i+1).padStart(2,'0')} · ${x}</summary><textarea class="edit owner-data" data-key="${i}" style="min-height:90px" aria-label="${x}" placeholder="[ĐIỀN THỰC TẾ]">${esc(read('owner-'+i,''))}</textarea></details>`).join('')}<button class="btn primary no-print" id="save-owner" style="margin-top:20px">Lưu thông tin</button><p>Ghi thông tin tại đây chưa phải phê duyệt hoặc thay đổi SOP.</p></div><div class="panel"><h2>Document Master List</h2>${sopTable(sops)}</div>`}
let skills=read('skills',[]),activeRecord=null;
function drawSkills(){document.getElementById('skill-table').innerHTML=`<table><thead><tr><th>Nhân viên</th>${['Bếp','Prep','Service','Cashier','Cleaning','QC'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${skills.length?skills.map((r,i)=>`<tr><td><input class="skill-name" data-i="${i}" value="${esc(r.name)}" placeholder="Họ tên" aria-label="Tên nhân viên ${i+1}" style="width:140px"></td>${r.levels.map((l,j)=>`<td><select class="skill-level" data-i="${i}" data-j="${j}" aria-label="Kỹ năng ${j+1} nhân viên ${i+1}">${['Beginner','Trained','Certified'].map(x=>`<option ${x===l?'selected':''}>${x}</option>`).join('')}</select></td>`).join('')}</tr>`).join(''):'<tr><td colspan="7" class="empty">Chưa có nhân viên. Thêm để tạo ma trận thực tế.</td></tr>'}</tbody></table>`}
function collectSkills(){document.querySelectorAll('.skill-name').forEach(e=>skills[e.dataset.i].name=e.value);document.querySelectorAll('.skill-level').forEach(e=>skills[e.dataset.i].levels[e.dataset.j]=e.value)}
function countChecks(){let count=[...document.querySelectorAll('[data-status]')].filter(x=>x.value==='Đạt').length;document.getElementById('check-count').textContent=count+' / 14 nội dung đã đạt';document.getElementById('check-progress').style.width=count/14*100+'%'}
function download(value,name){let url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(route){if(route==='home')document.getElementById('home-search').onkeydown=e=>{if(e.key==='Enter'){sessionStorage.setItem('searchQuery',e.target.value);location.hash='library'}};
if(route==='library'){let inp=document.getElementById('search'),filter=document.getElementById('filter');let update=()=>{let q=inp.value.toLocaleLowerCase('vi');document.getElementById('sop-rows').innerHTML=sopRows(sops.filter(s=>(filter.value==='all'||s.module==filter.value)&&(s.title+' '+s.code+' '+s.owner).toLocaleLowerCase('vi').includes(q)))};inp.oninput=filter.onchange=update;inp.value=sessionStorage.getItem('searchQuery')||'';sessionStorage.removeItem('searchQuery');update()}
if(route.startsWith('sop/')){let b=document.getElementById('save-note');if(b)b.onclick=()=>{if(write('notes-'+route.split('/')[1],document.getElementById('sop-note').value))toast('Đã lưu ghi chú tại trình duyệt.')}}
if(route==='training'){drawSkills();document.getElementById('add-staff').onclick=()=>{collectSkills();skills.push({name:'',levels:Array(6).fill('Beginner')});drawSkills()};document.getElementById('save-skills').onclick=()=>{collectSkills();if(write('skills',skills))toast('Đã lưu ma trận kỹ năng.')}}
if(route==='documents')document.getElementById('save-owner').onclick=()=>{let ok=true;document.querySelectorAll('.owner-data').forEach(e=>ok=write('owner-'+e.dataset.key,e.value)&&ok);if(ok)toast('Đã lưu thông tin. SOP vẫn là bản dự thảo.')};
if(route==='checklists'){document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{document.querySelector(`[data-status="${e.dataset.check}"]`).value=e.checked?'Đạt':'Chưa hướng dẫn';countChecks()});document.querySelectorAll('[data-status]').forEach(e=>e.onchange=()=>{document.querySelector(`[data-check="${e.dataset.status}"]`).checked=e.value==='Đạt';countChecks()});document.getElementById('save-record').onclick=()=>{let value=id=>document.getElementById(id).value.trim();if(!value('employee')||!value('branch')||!value('record-date')){toast('Điền nhân viên, chi nhánh và ngày trước khi lưu.');return}let r={id:activeRecord||crypto.randomUUID(),employee:value('employee'),branch:value('branch'),date:value('record-date'),trainer:value('trainer'),reviewer:value('reviewer'),position:value('position'),items:checklistItems.map((title,i)=>({title,status:document.querySelector(`[data-status="${i}"]`).value,note:document.querySelector(`[data-note="${i}"]`).value}))};let all=read('trainingRecords',[]),index=all.findIndex(a=>a.id===r.id);if(index<0)all.push(r);else all[index]=r;if(write('trainingRecords',all)){render();toast('Đã lưu phiếu đào tạo.')}};document.getElementById('export-records').onclick=()=>download(read('trainingRecords',[]),'phieu-dao-tao.json');document.querySelectorAll('.load-record').forEach(e=>e.onclick=()=>{let r=read('trainingRecords',[]).find(x=>x.id===e.dataset.id);if(!r)return;activeRecord=r.id;['employee','branch','trainer','reviewer','position'].forEach(id=>document.getElementById(id).value=r[id]||'');document.getElementById('record-date').value=r.date;r.items.forEach((it,i)=>{document.querySelector(`[data-status="${i}"]`).value=it.status;document.querySelector(`[data-check="${i}"]`).checked=it.status==='Đạt';document.querySelector(`[data-note="${i}"]`).value=it.note});countChecks();window.scrollTo({top:0,behavior:'smooth'});toast('Đang sửa phiếu đã lưu. Lưu để cập nhật.')} )}}
function render(){const route=location.hash.slice(1)||'home';activeRecord=null;const links=[['home','◈','Tổng quan'],['library','▤','Thư viện SOP'],['checklists','✓','Checklist đào tạo'],['training','↗','Đào tạo & kỹ năng'],['documents','▧','Kiểm soát tài liệu']];document.getElementById('nav').innerHTML=links.map(([id,icon,name])=>`<a href="#${id}" class="${route===id?'active':''}"><span>${icon}</span>${name}</a>`).join('')+'<div class="divider"></div>'+[0,1].map(i=>`<a href="#module/${i}" class="${route==='module/'+i?'active':''}"><span>${String(i).padStart(2,'0')}</span>${moduleVi[i]}</a>`).join('');let html=route==='home'?home():route==='library'?library():route==='checklists'?checklists():route==='training'?training():route==='documents'?documents():route.startsWith('module/')?modulePage(Number(route.split('/')[1])):route.startsWith('sop/')?detail(route.split('/')[1]):'<div class="empty">Trang không tồn tại. <a href="#home">Về tổng quan</a></div>';document.getElementById('main').innerHTML=html;document.getElementById('crumb').textContent='Không gian vận hành / '+(links.find(x=>x[0]===route)?.[2]||'Thư viện SOP');document.getElementById('sidebar').classList.remove('open');bind(route);window.scrollTo(0,0)}
document.getElementById('menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');window.addEventListener('hashchange',render);render();
